function fmtDay(d){ function p(x){ return (x<10?'0':'')+x; } return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate()); }
function workdays(start, end, opts){
  opts=opts||{};
  var s=start? new Date(start) : new Date();
  var e=end? new Date(end) : new Date();
  if(isNaN(s.getTime()) || isNaN(e.getTime())) return {ok:false, reason:'invalid date'};
  if(s.getTime()>e.getTime()){ var tmp=s; s=e; e=tmp; }
  var hol={}; var hs=opts.holidays||[];
  if(typeof hs==='string') hs=hs.split(/[\s,，;；\n]+/);
  for(var i=0;i<hs.length;i++){ var k=String(hs[i]).trim(); if(k) hol[k]=1; }
  var d=new Date(s.getFullYear(), s.getMonth(), s.getDate());
  var out=[];
  while(d.getTime()<=e.getTime()){
    var wd=d.getDay();
    if(wd!==0 && wd!==6){ var key=fmtDay(d); if(!hol[key]) out.push(key); }
    d.setDate(d.getDate()+1);
  }
  var lim=opts.preview!=null?opts.preview:10;
  return {ok:true, days:out.length, dates:out.slice(0,lim)};
}

var EXPORTS={workdays:workdays,fmtDay:fmtDay};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WorkdayForgePure = EXPORTS; }
